{"kind": "content", "icon": "🧮", "head": "एक उदाहरण से घनत्व निकालना", "points": ["क्षेत्रफल दस हज़ार वर्ग किलोमीटर", "जनसंख्या बीस लाख", "घनत्व = 20,00,000 ÷ 10,000", "उत्तर दो सौ व्यक्ति प्रति वर्ग किमी", "इसकी तुलना दूसरे क्षेत्र से"], "say": "मान लीजिए किसी क्षेत्र का क्षेत्रफल दस हज़ार वर्ग किलोमीटर है और जनसंख्या बीस लाख है। घनत्व निकालने के लिए बीस लाख को दस हज़ार से भाग दीजिए। उत्तर दो सौ व्यक्ति प्रति वर्ग किलोमीटर आएगा। अब इस घनत्व की तुलना किसी दूसरे क्षेत्र से कीजिए तो पता चलेगा कि कौन सा क्षेत्र अधिक घना है। परीक्षा में ऐसे छोटे प्रश्न आसानी से पूछे जाते हैं।", "ext": 2},
{"kind": "content", "icon": "🧓", "head": "आयु संरचना और जनसंख्या पिरामिड", "points": ["जनसंख्या को तीन आयु वर्गों में बाँटना", "युवा, वयस्क और वृद्ध", "पिरामिड की आकृति से अनुमान", "विस्तारी, स्थिर और संकुचित पिरामिड", "विकसित और विकासशील देशों में अंतर"], "say": "जनसंख्या को सामान्यतः तीन आयु वर्गों में बाँटा जाता है, बच्चे, वयस्क और वृद्ध। इनका चित्र जनसंख्या पिरामिड के रूप में बनाया जाता है। विकासशील देशों में पिरामिड का आधार चौड़ा होता है क्योंकि बच्चे ज़्यादा होते हैं। विकसित देशों में पिरामिड संकरा होता है क्योंकि बच्चे कम और वृद्ध अधिक होते हैं। पिरामिड की आकृति से भविष्य की जनसंख्या का अनुमान लगाया जा सकता है।", "ext": 3},
{"kind": "content", "icon": "⚖️", "head": "लिंग अनुपात और साक्षरता", "points": ["प्रति हज़ार पुरुषों पर महिलाएँ", "विश्व में लगभग संतुलित", "भारत में अनुपात की चिंता", "साक्षरता का अर्थ", "शिक्षा और विकास का संबंध"], "say": "लिंग अनुपात का अर्थ है प्रति हज़ार पुरुषों पर महिलाओं की संख्या। विश्व में यह लगभग संतुलित रहता है पर भारत जैसे कुछ देशों में इसमें असमानता की चिंता रही है। साक्षरता का अर्थ है पढ़ने और लिखने की क्षमता। शिक्षा का स्तर जितना बेहतर होता है उतना ही देश का सामाजिक और आर्थिक विकास होता है। इसीलिए जनसंख्या की गुणवत्ता में साक्षरता बड़ा संकेतक है।", "ext": 3},
{"kind": "content", "icon": "🏙️", "head": "नगरीकरण और प्रवास", "points": ["गाँव से शहर की ओर प्रवास", "काम और बेहतर जीवन की तलाश", "धकेलने और खींचने वाले कारक", "शहरों पर दबाव", "गाँवों पर प्रभाव"], "say": "प्रवास का अर्थ है लोगों का एक स्थान से दूसरे स्थान जाना। भारत में बहुत लोग गाँव से शहर की ओर जाते हैं। इसके कारण दो प्रकार के होते हैं, धकेलने वाले कारक जैसे गरीबी और बेरोज़गारी और खींचने वाले कारक जैसे रोज़गार और बेहतर सुविधाएँ। प्रवास से शहरों पर दबाव बढ़ता है और गाँव की श्रमशक्ति घटती है। साथ ही पैसा गाँव में आने से कुछ लाभ भी होता है।", "ext": 3},
{"kind": "content", "icon": "🌍", "head": "जनसंख्या के आँकड़े कहाँ से आते हैं", "points": ["जनगणना: हर दस साल", "नमूना सर्वेक्षण", "जन्म-मृत्यु पंजीकरण", "भारत में पहली जनगणना 1872"], "say": "जनसंख्या के आँकड़े कई स्रोतों से मिलते हैं। सबसे भरोसेमंद स्रोत जनगणना है, जिसमें हर घर जाकर गिनती होती है। भारत में हर दस साल पर जनगणना होती है। इसके अलावा नमूना सर्वेक्षण और जन्म तथा मृत्यु के पंजीकरण से भी जानकारी मिलती है। भारत में पहली क्रमबद्ध जनगणना अठारह सौ इकहत्तर के आसपास शुरू हुई। इन आँकड़ों से सरकार स्कूल, अस्पताल और राशन की योजना बनाती है।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "जनगणना भारत में कितने वर्ष में होती है?", "a": "हर 10 वर्ष में", "pause": 4, "say": "याद कीजिए... भारत में जनगणना हर दस साल में होती है, यानी दशक में एक बार। अलग-अलग वर्षों के आँकड़ों की तुलना करके हम देखते हैं कि आबादी कितनी बढ़ी और किस तरफ़ बढ़ी।", "ext": 7},
{"kind": "content", "icon": "⛰️", "head": "वितरण को प्रभावित करने वाले भौतिक कारक", "points": ["जलवायु: सम और आरामदायक", "भूमि: मैदान घने, पहाड़ विरल", "मिट्टी: उपजाऊ जलोढ़", "जल की उपलब्धता"], "say": "जहाँ जीवन आसान है, वहाँ लोग ज़्यादा रहते हैं। मैदानी इलाक़ों में खेती और यातायात आसान होता है, इसलिए गंगा के मैदान में आबादी बहुत घनी है। पहाड़, रेगिस्तान और बहुत ठंडे इलाक़ों में कम लोग रहते हैं। उपजाऊ जलोढ़ मिट्टी और पानी की आसान उपलब्धता भी लोगों को खींचती है। इसीलिए सभ्यताएँ नदियों के किनारे पनपीं, जैसे सिंधु और गंगा की घाटी।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "गंगा का मैदान घना क्यों बसा है?", "a": "उपजाऊ मिट्टी, पर्याप्त जल, समतल भूमि और अनुकूल जलवायु के कारण", "pause": 4, "say": "कारण सोचिए... यहाँ की जलोढ़ मिट्टी बहुत उपजाऊ है, नदियों से पानी आसानी से मिलता है, भूमि समतल है इसलिए सड़क और रेल बनाना सरल है, और जलवायु भी खेती के अनुकूल है। इन सभी कारणों से यहाँ आबादी बहुत घनी है।", "ext": 7},
{"kind": "content", "icon": "🏭", "head": "आर्थिक और सामाजिक कारक", "points": ["खनिज और उद्योग", "नगरीकरण", "परिवहन के साधन", "राजनीतिक स्थिरता"], "say": "सिर्फ़ प्रकृति ही नहीं, आर्थिक कारण भी आबादी तय करते हैं। जहाँ खनिज मिलते हैं और उद्योग लगते हैं, वहाँ रोज़गार के लिए लोग आकर बस जाते हैं, जैसे झारखंड में जमशेदपुर और धनबाद। नगरों में सुविधाएँ ज़्यादा होती हैं, इसलिए लोग शहरों की ओर जाते हैं। अच्छा परिवहन, शांति और सरकार की नीतियाँ भी लोगों को बसने में मदद करती हैं। जहाँ युद्ध या अशांति हो, वहाँ से लोग पलायन करते हैं।", "ext": 7, "img": "p2_baby.jpg", "cap": "शिशु · फ़ोटो: PxHere (CC0)"},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "दो आर्थिक कारक बताइए जो जनसंख्या वितरण को प्रभावित करते हैं।", "a": "खनिज/उद्योग और परिवहन (या नगरीकरण)", "pause": 4, "say": "सोचिए... उद्योग लगने से रोज़गार बढ़ता है और लोग वहाँ बसते हैं। परिवहन साधन अच्छे हों तो व्यापार बढ़ता है और बस्तियाँ फैलती हैं। इसलिए खनिज और उद्योग तथा परिवहन दो मुख्य आर्थिक कारक हैं।", "ext": 7},
{"kind": "content", "icon": "📏", "head": "घनत्व: सूत्र और प्रकार", "points": ["घनत्व = जनसंख्या ÷ क्षेत्रफल", "अंकगणितीय घनत्व", "शारीरिक घनत्व", "कृषि घनत्व"], "say": "घनत्व बताता है कि प्रति वर्ग किलोमीटर कितने लोग रहते हैं। सूत्र है कुल जनसंख्या भाग कुल क्षेत्रफल। इसे अंकगणितीय घनत्व कहते हैं। शारीरिक घनत्व में जनसंख्या को केवल खेती योग्य भूमि से भाग देते हैं, इसलिए यह जीवन के दबाव को बेहतर दिखाता है। कृषि घनत्व में कृषकों की संख्या को शुद्ध बोए गए क्षेत्र से भाग देते हैं। विकासशील देशों में शारीरिक घनत्व अकसर ज़्यादा होता है।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "किसी राज्य की जनसंख्या 12 करोड़ और क्षेत्रफल 1 लाख वर्ग किमी है। घनत्व क्या होगा?", "a": "12,00,00,000 ÷ 1,00,000 = 1200 व्यक्ति प्रति वर्ग किमी", "pause": 4, "say": "सूत्र लगाइए... जनसंख्या बारह करोड़ और क्षेत्रफल एक लाख वर्ग किलोमीटर। बारह करोड़ को एक लाख से भाग देने पर बारह सौ आता है। यानी हर वर्ग किलोमीटर में बारह सौ लोग रहते हैं। यह घना क्षेत्र है।", "ext": 7},
{"kind": "content", "icon": "📈", "head": "वृद्धि के घटक: जन्म, मृत्यु, प्रवास", "points": ["प्राकृतिक वृद्धि = जन्म दर − मृत्यु दर", "प्रवास: आव्रजन और उत्प्रवास", "वास्तविक वृद्धि = प्राकृतिक + प्रवास", "धनात्मक और ऋणात्मक वृद्धि"], "say": "जनसंख्या तीन बातों से बदलती है, जन्म, मृत्यु और प्रवास। प्राकृतिक वृद्धि जन्म दर में से मृत्यु दर घटाने पर मिलती है। प्रवास में बाहर से आने को आव्रजन और बाहर जाने को उत्प्रवास कहते हैं। इन दोनों को जोड़कर वास्तविक वृद्धि निकलती है। अगर जन्म दर मृत्यु दर से ज़्यादा है तो वृद्धि धनात्मक है, और अगर कम है तो जनसंख्या घट भी सकती है, जैसे कुछ यूरोपीय देशों में।", "ext": 7},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "जन्म दर 25 और मृत्यु दर 10 प्रति हज़ार हो तो प्राकृतिक वृद्धि दर?", "a": "25 − 10 = 15 प्रति हज़ार (1.5%)", "pause": 4, "say": "घटाइए... जन्म दर पच्चीस में से मृत्यु दर दस घटाने पर पंद्रह आता है। यह प्रति हज़ार की दर है, यानी डेढ़ प्रतिशत। इतनी दर से आबादी बढ़ती रहे तो कुछ दशकों में दुगुनी हो जाती है।", "ext": 7},
